package com.adent.orders.api; import com.adent.orders.domain.RadiologyOrder; import com.adent.orders.repository.RadiologyOrderRepository; import com.adent.patient.repository.PatientRepository; import com.adent.shared.exception.NotFoundException; import com.adent.shared.security.CurrentUser; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.time.*; import java.util.*; @RestController @RequestMapping("/api/radiology") @PreAuthorize("hasAnyRole('OWNER','DENTIST','XRAY_TECHNICIAN')") public class RadiologyController { private final CurrentUser current;private final RadiologyOrderRepository repo;private final PatientRepository patients;public RadiologyController(CurrentUser c,RadiologyOrderRepository r,PatientRepository p){current=c;repo=r;patients=p;} @GetMapping public List<RadiologyOrder> list(){return repo.findByTenantIdOrderByCreatedAtDesc(current.tenantId());}@GetMapping("/patient/{id}") public List<RadiologyOrder> patient(@PathVariable UUID id){return repo.findByTenantIdAndPatientIdOrderByCreatedAtDesc(current.tenantId(),id);}@PostMapping @PreAuthorize("hasRole('DENTIST')") public RadiologyOrder create(@RequestBody Request r){patients.findByIdAndTenantId(r.patientId(),current.tenantId()).orElseThrow(()->new NotFoundException("Paciente no encontrado"));RadiologyOrder o=new RadiologyOrder();o.setTenantId(current.tenantId());o.setPatientId(r.patientId());o.setEncounterId(r.encounterId());o.setRequestedByStaffId(r.requestedByStaffId());o.setStudyType(r.studyType());o.setToothCodes(r.toothCodes());o.setInstructions(r.instructions());return repo.save(o);}@PatchMapping("/{id}/result") @PreAuthorize("hasRole('XRAY_TECHNICIAN')") public RadiologyOrder result(@PathVariable UUID id,@RequestParam String status,@RequestParam(required=false) String resultUrl,@RequestParam(required=false) String notes){RadiologyOrder o=repo.findByIdAndTenantId(id,current.tenantId()).orElseThrow(()->new NotFoundException("Orden no encontrada"));o.setStatus(status);o.setResultUrl(resultUrl);o.setResultNotes(notes);if("DELIVERED".equals(status))o.setDeliveredAt(OffsetDateTime.now());return repo.save(o);} public record Request(UUID patientId,UUID encounterId,UUID requestedByStaffId,String studyType,String toothCodes,String instructions){} }
